import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import {
  CardStatsSkeleton,
  LatestInvoicesSkeleton,
  RevenueChartSkeleton,
} from './DashboardSkeleton'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')
  return (await res.json()) as DashboardData
}

async function DashboardStats({ data }: { data: Promise<DashboardData> }) {
  const { totalRevenue, totalInvoices } = await data

  return (
    <CardStats
      totalRevenue={totalRevenue}
      totalInvoices={totalInvoices}
    />
  )
}

async function DashboardRevenue({ data }: { data: Promise<DashboardData> }) {
  const { revenue } = await data

  return <RevenueChart revenue={revenue} />
}

async function DashboardInvoices({ data }: { data: Promise<DashboardData> }) {
  const { invoices } = await data

  return <LatestInvoices invoices={invoices} />
}

export default function Page() {
  // Start the request before rendering any of the dynamic dashboard sections.
  // Each section awaits the same promise, so the request is only made once.
  const dashboardData = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <DashboardStats data={dashboardData} />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <DashboardRevenue data={dashboardData} />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <DashboardInvoices data={dashboardData} />
      </Suspense>
    </main>
  )
}
export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-busy="true">
      <div className="card skeleton-card">
        <h2>Total Revenue</h2>
        <p className="skeleton-text">Loading...</p>
      </div>
      <div className="card skeleton-card">
        <h2>Total Invoices</h2>
        <p className="skeleton-text">Loading...</p>
      </div>
    </div>
  )
}

export function RevenueChartSkeleton() {
  return (
    <div className="chart skeleton-card" aria-busy="true">
      <h2>Revenue</h2>
      <p className="skeleton-text">Loading revenue...</p>
    </div>
  )
}

export function LatestInvoicesSkeleton() {
  return (
    <div className="invoices skeleton-card" aria-busy="true">
      <h2>Latest Invoices</h2>
      <p className="skeleton-text">Loading invoices...</p>
    </div>
  )
}

export function DashboardSkeleton() {
  return (
    <main>
      <h1>Dashboard</h1>
      <CardStatsSkeleton />
      <RevenueChartSkeleton />
      <LatestInvoicesSkeleton />
    </main>
  )
}
import { DashboardSkeleton } from './DashboardSkeleton'

export default function Loading() {
  return <DashboardSkeleton />
}
